sys_ui_policy.script_true:
function onCondition() {
	// This is only for loading an existing record with a service.
	if (g_form.isNewRecord())
		return;

	g_scratchpad.previousService = g_form.getValue('hr_service');	

	// Show HR Service fields controlled in OHS scope
	var SCOPE_OHS = '6a9d3c8a2f0f68904cbeb1e72799b67b';
	if (g_scratchpad.fieldsByScope && g_scratchpad.fieldsByScope.hasOwnProperty(SCOPE_OHS)) {
		// Set fields to read only if case is in a closed state
		var setReadOnly = ['3', '4', '7'].indexOf(g_form.getValue('state')) > -1; 

		var fields = g_scratchpad.fieldsByScope[SCOPE_OHS];

		for (var i = 0; i < fields.length; i++) {
			g_form.setDisplay(fields[i].trim(), true);
			if (setReadOnly)
				g_form.setReadOnly(fields[i].trim(), true);
		}
	}

	if (g_scratchpad.subjectPersonRelatedLists) {
		var relatedListsArr = g_scratchpad.subjectPersonRelatedLists.split(',');
		// We only need to show hidden related lists, as they only appear on an existing record (not on create so the service cannot change)
		for (var j = 0; j < relatedListsArr.length; j++)
			g_form.showRelatedList("REL:" + relatedListsArr[j].trim());
	}
}
